<?php

/** UI explanations for the fields supported by ProtocolOptions, not arbitrary core settings. */
final class ProtocolOptionHelp
{
    public static function text(string $protocol, string $path): string
    {
        if ($protocol === 'masque') return match ($path) {
            'client', 'client.http' => 'h3: HTTP/3 через UDP (по умолчанию); h2: HTTP/2 через TCP. Оба передают TCP и UDP приложений. Требуется Xray 26.9.30+. После изменения скачайте профиль заново.',
            'client.connections' => 'XMUX: сколько туннелей CONNECT-IP клиент держит одновременно и распределяет между ними соединения, 1–4. Каждый туннель — отдельное QUIC- или TCP-соединение и отдельный адрес в пуле сервера. Работает в Xray 26.10.17+ и форке 26.10.13+, старые клиенты настройку не учитывают. Сброс — один туннель.',
            'client.reuse' => 'XMUX: сколько секунд туннель принимает новые соединения, затем клиент открывает новый; начатые соединения доживают в старом. Число или диапазон 60–86400, например 1800-3000 (так ядро делает по умолчанию). Работает в Xray 26.10.17+ и форке 26.10.13+.',
            'noise', 'noise.enabled' => 'UDP finalmask на сервере MASQUE и в профиле клиента h3. По умолчанию выключен; включение без своего списка выбирает динамический exp. HTTP/2 не использует UDP-маскировку. Дополнительные пакеты увеличивают трафик и не гарантируют обход блокировок.',
            'noise.reset' => 'Время без исходящих UDP-пакетов к адресу, после которого следующая отправка повторяет шум: число или диапазон 1–86400 секунд. По умолчанию 60-120. При непрерывном трафике это не периодический таймер.',
            'noise.packets' => 'JSON, до 8 пакетов по 1400 байт: [{"type":"exp","packet":"<b 0d0a><t><c><n><rc 20-40>","delay":"1-3"}]. Типы: rand, str, hex, base64, exp. exp: <b hex>, <r N-M>, <rc N-M> буквы, <rd N-M> цифры, <t> время, <c> счётчик, <n> nonce. delay 0–1000 мс. Сброс возвращает динамический шаблон.',
            default => 'Настройки MASQUE применяются к отдельному сервису; выбор версии основного Xray на него не влияет.',
        };
        $field = substr($path, (int) strrpos('.' . $path, '.'));
        $text = match ($field) {
            'server' => 'Параметры ядра на VPN-сервере. Сохраняются и применяются автоматически; изменение может прервать соединения этого протокола.',
            'client' => 'Общие параметры совместимых клиентов. Сохранение меняет выдаваемые профили; на устройстве обновите подписку или импортируйте профиль заново.',
            'singbox' => 'Эти параметры попадают только в JSON sing-box. Они не меняют сервер и настройки Mihomo.',
            'mihomo' => 'Эти параметры попадают только в профили Mihomo. Они не меняют сервер и sing-box.',
            'native' => 'Настройки отдельного приложения Mieru: локальные порты, MTU и журнал. Не применяются к Mihomo; полный набор переносится в нативный JSON.',
            'log_level', 'loggingLevel' => 'Подробность журнала: trace/TRACE — все подробности, debug/DEBUG — диагностика, info/INFO — обычные события, warn/WARN — предупреждения, error/ERROR — ошибки, fatal/FATAL — критические ошибки, panic — только аварии. Подробный журнал занимает больше места.',
            'dns_server' => 'IP DNS-сервера, через который VPN-сервер разрешает имена назначений. Это не DNS на клиентском устройстве.',
            'tcp_fast_open', 'tfo' => 'TCP Fast Open: разрешает отправить первые данные при установлении TCP-соединения. Выключено — обычное соединение. Требуется поддержка ОС и сети.',
            'tcp_multi_path', 'mptcp' => 'Multipath TCP: разрешает одному соединению использовать несколько сетевых путей. Выключено — обычный TCP. Требуется поддержка MPTCP обеими сторонами и ОС.',
            'disable_tcp_keep_alive' => 'Включено — отключить TCP keepalive-пробы; выключено — разрешить их. Пробы помогают обнаружить пропавшее соединение.',
            'tcp_keep_alive' => 'Сколько соединение TCP может бездействовать до первой keepalive-пробы. Не действует при отключённом keepalive.',
            'tcp_keep_alive_interval' => 'Интервал между TCP keepalive-пробами. Меньше — быстрее проверка связи, больше служебных пакетов.',
            'padding_scheme' => 'Правила дополнения первых пакетов AnyTLS до заданных размеров. JSON-массив, например ["stop=2","0=30-30","1=100-400"]. stop задаёт конец схемы; строки N=min-max — размеры для пакета N. Увеличивает трафик; сброс возвращает штатную схему.',
            'tls' => 'Согласование TLS: версии, ALPN и криптографические параметры. Настройки клиента и сервера должны быть совместимы; TUIC и ShadowTLS требуют TLS 1.3.',
            'alpn' => 'Протоколы внутри TLS в порядке предпочтения, например ["h3"] для TUIC, ["http/1.1"] для сайта прикрытия AnyTLS. Нужен хотя бы один общий вариант у клиента и сервера.',
            'min_version' => 'Самая старая разрешённая версия TLS: 1.2 или 1.3. Повышение минимума исключает старые клиенты; для TUIC и ShadowTLS доступна только 1.3.',
            'max_version' => 'Самая новая разрешённая версия TLS. 1.2 ограничивает соединение TLS 1.2; 1.3 разрешает TLS 1.3. Минимум не должен быть выше максимума.',
            'cipher_suites' => 'Разрешённые наборы шифров TLS 1.2: AES-GCM или ChaCha20-Poly1305; RSA/ECDSA должны подходить сертификату. На наборы TLS 1.3 этот список не влияет.',
            'curve_preferences' => 'Группы обмена ключами TLS в порядке предпочтения. P256/P384/P521 и X25519 — эллиптические кривые; X25519MLKEM768 — гибрид с постквантовым ML-KEM. Клиент и сервер должны поддерживать выбранную группу.',
            'handshake_timeout' => 'Предельное время согласования TLS. По истечении попытка соединения прекращается.',
            'fingerprint' => 'Вид первого TLS-сообщения ClientHello, отправляемого клиентом. Меняет отпечаток рукопожатия, но не превращает VPN в браузер и не гарантирует обход блокировок.',
            'idle_session_check_interval' => 'Как часто AnyTLS проверяет неиспользуемые сессии для закрытия. Задавайте целые секунды, например 30s.',
            'idle_session_timeout' => 'Как долго AnyTLS хранит неиспользуемую сессию перед закрытием. Повторное использование сокращает задержку новых подключений.',
            'min_idle_session' => 'Сколько свободных сессий AnyTLS сохранять при очистке. 0 разрешает закрыть все; большее число удерживает больше соединений.',
            'client_metadata' => 'Текстовая метка клиента, передаваемая серверу AnyTLS в поддерживающих её клиентах. Не является паролем и не изменяет разрешения доступа.',
            'udp' => 'Разрешить UDP приложений через AnyTLS. Выключено — остаётся TCP: Mihomo отключает UDP в профиле, сервер AnyTLS также отклоняет UDP. В общей подписке это не затрагивает UDP других протоколов и DNS шаблона.',
            'connect_timeout' => str_starts_with($path, 'server.handshake.')
                ? 'Сколько сервер ShadowTLS ждёт подключения к сайту прикрытия.' : 'Сколько клиент sing-box ждёт установления соединения с VPN-сервером.',
            'certificate_public_key_sha256' => 'Дополнительная проверка SHA-256 публичного ключа TLS-сертификата. Если ключ сертификата сменится, обновите пин в профиле. Обычная проверка сертификата сохраняется.',
            'fragment' => 'Разбить TLS-рукопожатие клиента на TCP-сегменты. Может увеличить задержку; сначала попробуйте record_fragment. Выключено — не запрашивать это разбиение.',
            'fragment_fallback_delay' => 'Задержка запасного способа фрагментации TLS, когда автоматический способ неприменим. Используется вместе с fragment.',
            'record_fragment' => 'Разбить TLS-рукопожатие клиента на несколько TLS-записей. Обычно требует меньше накладных расходов, чем TCP fragment.',
            'spoof' => 'Домен в подставном ClientHello перед настоящим рукопожатием. Только sing-box на клиенте; нужны сетевые права ОС (на Linux CAP_NET_RAW и CAP_NET_ADMIN). Реальный SNI и проверка TLS сохраняются.',
            'spoof_method' => 'Как сделать подставной TCP-сегмент неприемлемым для настоящего сервера. Сначала задайте spoof; поддержка зависит от ОС клиента.',
            'ip-version' => 'Какие IP-адреса использовать при разрешении имени сервера в Mihomo.',
            'disable-reuse' => 'Включено — отключить повторное использование сессий AnyTLS в Mihomo. Выключено — разрешить повторное использование и уменьшить число новых рукопожатий.',
            'udp_fragment' => 'Разрешить IP-фрагментацию исходящих UDP-пакетов сокета. Это не TUIC udp_mode и не TLS fragment. Работа зависит от ОС и пути до сервера.',
            'udp_timeout' => 'Сколько хранить неактивное UDP-состояние на сервере. После таймаута следующему обмену потребуется новое состояние.',
            'idle_timeout' => 'Таймаут простоя QUIC-соединения. После его истечения соединение закрывается.',
            'keep_alive_period' => 'Интервал служебных QUIC-пакетов для поддержания соединения и NAT. Меньший интервал увеличивает фоновый трафик.',
            'stream_receive_window', 'recv-window' => 'Максимальное окно приёма одного QUIC-потока в байтах. Больше — полезно на быстрых каналах с задержкой, но требует больше памяти.',
            'connection_receive_window', 'recv-window-conn' => 'Максимальное общее окно приёма QUIC-соединения в байтах. Оно не должно быть меньше окна одного потока.',
            'max_concurrent_streams', 'max-open-streams' => 'Предел одновременно открытых потоков QUIC. Больше — больше параллельных запросов и расход памяти.',
            'initial_packet_size' => 'Начальный размер исходящего QUIC-пакета в байтах. Слишком большой размер на узком MTU может помешать подключению.',
            'disable_path_mtu_discovery', 'disable-mtu-discovery' => 'Включено — отключить поиск подходящего размера QUIC-пакетов по пути. Выключено — разрешить автоматический подбор MTU.',
            'auth_timeout' => 'Сколько сервер TUIC ждёт успешной авторизации клиента перед закрытием соединения.',
            'heartbeat' => 'Интервал heartbeat-пакетов клиента TUIC для поддержания сеанса. Меньше — больше служебного трафика.',
            'zero_rtt_handshake' => 'Раннее согласование TUIC (0-RTT): уменьшает ожидание, но повышает риск повторного воспроизведения ранних запросов. По умолчанию выключено.',
            'udp_over_stream' => 'Включено — UDP приложений передаётся в надёжном потоке QUIC с повторной доставкой потерь. Выключено — используется выбранный native/quic. Может увеличивать задержку; транспорт до сервера остаётся UDP.',
            'request-timeout' => 'Таймаут запроса TUIC в Mihomo, в миллисекундах.',
            'max-udp-relay-packet-size' => 'Максимальный размер пакета для TUIC UDP relay в Mihomo, в байтах. Меняет упаковку UDP, а не порт сервера.',
            'fast-open' => 'Включено — Mihomo начинает установление TUIC лениво, при первом чтении/записи. Выключено — при создании соединения. Это не TCP Fast Open и не переключатель 0-RTT.',
            'cwnd' => 'Начальное окно перегрузки TUIC в Mihomo, в пакетах. Большое значение ускоряет старт, но может усилить потери; учитывается поддерживающим его алгоритмом.',
            'bbr-profile' => 'Режим BBR в Mihomo: применяется при выбранном алгоритме bbr.',
            'max-datagram-frame-size' => 'Максимальный размер QUIC DATAGRAM, объявляемый Mihomo, в байтах. Влияет на передачу UDP внутри QUIC.',
            'handshake' => 'Подключение сервера ShadowTLS к сайту прикрытия: порт и параметры TCP. Это отдельное соединение, не внешний VPN-порт.',
            'server_port' => 'TLS-порт сайта прикрытия, к которому подключается ShadowTLS. Для собственного сайта фиксирован 10443. Не меняет порт входа пользователей.',
            'multiplex' => 'Несколько потоков внутреннего Shadowsocks в одном соединении. Настройка переносится на сервер и клиентов; обновите их профили вместе. По умолчанию выключено, при включении выбран smux.',
            'enabled' => 'Включить объединение потоков Shadowsocks. Выключено — отдельные соединения. После смены обновите профили клиентов.',
            'padding' => $path === 'multiplex.padding'
                ? 'Включено — дополнять мультиплексированные потоки служебными байтами; сервер потребует такой же режим клиента. Выключено — без дополнения.'
                : 'Дополнительные случайные байты в середине и конце сегмента Mieru. Меняют размеры пакетов и увеличивают трафик.',
            'protocol' => 'Формат объединения потоков: smux — лёгкий мультиплексор (штатный выбор бота), yamux — другой формат мультиплексирования, h2mux — на основе HTTP/2. Для h2mux нужен клиент с исправлением GO-2026-4918; штатный Mihomo 1.19.32 содержит старый x/net.',
            'max_connections' => 'Максимум соединений для мультиплексирования. В каждом могут передаваться несколько потоков.',
            'min_streams' => 'Минимум потоков в соединении перед открытием следующего. Не задавайте одновременно с ненулевым max_streams.',
            'max_streams' => 'Предел потоков в одном соединении перед открытием следующего. 0 — без этого ограничения. Не задавайте одновременно с ненулевым min_streams.',
            'mtu' => 'MTU транспорта Mieru в байтах. Меньший размер полезен на путях с ограниченным MTU; этот параметр не переносится в Mihomo.',
            'advancedSettings' => 'Дополнительные серверные параметры Mieru: журнал метрик и проверка подсказки пользователя.',
            'metricsLoggingInterval' => 'Как часто Mieru пишет метрики в журнал. Короткий интервал создаёт больше записей.',
            'userHintIsMandatory' => 'Включено — Mieru требует подсказку идентификации пользователя от клиента; старые клиенты без неё не подключатся. Выключено — подсказка необязательна.',
            'dns' => 'Разрешение имён на сервере Mieru: выбор IPv4/IPv6 и точечные соответствия доменов адресам.',
            'dualStack' => 'Как сервер Mieru выбирает адрес, если DNS возвращает IPv4 и IPv6.',
            'hosts' => 'Локальные соответствия домен → IP для DNS Mieru, например {"example.com":"203.0.113.10"}. Для этих имён применяется заданный адрес.',
            'trafficPattern' => 'Рисунок отправляемого трафика Mieru: разбиение, префиксы и дополнение. Клиент и сервер настраивают свой исходящий трафик независимо.',
            'seed' => 'Число для воспроизводимого выбора не заданных явно параметров рисунка Mieru. Одинаковый seed сохраняет выбор; это не пароль и не ключ шифрования.',
            'unlockAll' => 'Включено — автоматический выбор рисунка Mieru может использовать все варианты, включая затратные. Выключено — только ограниченный набор. Явно заданные поля доступны в обоих режимах.',
            'tcpFragment' => 'Дополнительное разбиение TCP-трафика Mieru на фрагменты с паузами. Может повысить задержку.',
            'enable' => 'Включить дополнительное TCP-разбиение Mieru. Выключено — без этого разбиения.',
            'maxSleepMs' => 'Максимальная пауза между TCP-фрагментами Mieru, в миллисекундах. 0 — без дополнительной паузы.',
            'nonce' => 'Внешний вид первых байтов nonce Mieru. Меняет наблюдаемый префикс пакета; не задаёт пароль пользователя.',
            'type' => 'Способ выбора префикса nonce Mieru.',
            'applyToAllUDPPacket' => 'Включено — рисунок nonce применяется ко всем UDP-пакетам Mieru. Выключено — только к первому пакету.',
            'minLen' => 'Минимум изменяемых байтов префикса nonce, от 0 до 12. Используется в PRINTABLE/PRINTABLE_SUBSET; игнорируется в RANDOM/FIXED.',
            'maxLen' => 'Максимум изменяемых байтов префикса nonce, до 12. Должен быть не меньше minLen. Используется в PRINTABLE/PRINTABLE_SUBSET.',
            'customHexStrings' => 'Варианты префикса nonce в HEX без 0x, например ["010203","aabb"]. В режиме FIXED каждый раз выбирается один из списка; в остальных режимах список не используется.',
            'maxMiddlePaddingLen' => 'Максимум дополнительных байтов в середине сегмента Mieru. 0 отключает это дополнение; сброс возвращает выбор ядра.',
            'maxEndPaddingLen' => 'Максимум дополнительных байтов в конце сегмента Mieru. 0 отключает это дополнение; сброс возвращает выбор ядра.',
            'lowEntropy' => 'Добавление битов-заполнителей к зашифрованному трафику Mieru для снижения его внешней случайности. Размер передаваемого тела увеличивается.',
            'mode' => 'Доля полезных битов в каждом 64-битном блоке Mieru: OFF — без перекодирования; 32 — 32+32 бита (×2); 40 — 40+24 (×1,6); 48 — 48+16 (×1,33); 56 — 56+8 (×1,14). Меньше полезных битов — больше трафика.',
            'maskRotation' => 'Поворот маски битов-заполнителей между блоками Mieru. NO_ROTATION — без поворота; RIGHT_1…15 / LEFT_1…15 — вправо/влево на указанное число бит. Не действует при выключенном lowEntropy.',
            'multiplexing' => 'Сколько логических соединений Mieru объединять в одном транспортном соединении. OFF — не объединять; LOW — мало, MIDDLE — средне, HIGH — много. Большее объединение экономит соединения, но усиливает их взаимное влияние.',
            'handshakeMode' => 'HANDSHAKE_STANDARD — дождаться ответа сервера; HANDSHAKE_NO_WAIT — отправлять данные без этого ожидания. NO_WAIT уменьшает задержку старта, но результат авторизации станет известен позже.',
            'socks5Port' => 'Локальный SOCKS5-порт отдельного приложения Mieru на устройстве клиента. Не является внешним портом VPN-сервера.',
            'rpcPort' => 'Локальный управляющий RPC-порт отдельного приложения Mieru. Должен отличаться от SOCKS5 и HTTP-порта.',
            'httpProxyPort' => 'Локальный HTTP-прокси порт отдельного приложения Mieru. Сброс убирает явную настройку этого порта; это не порт сервера.',
            default => '',
