        $choices = match ($field) {
            'fingerprint' => ['default' => 'не задавать отпечаток в профиле; выбор клиента', 'chrome' => 'ClientHello Chrome',
                'firefox' => 'ClientHello Firefox', 'edge' => 'ClientHello Edge', 'safari' => 'ClientHello Safari', 'ios' => 'ClientHello Safari на iOS',
                'random' => 'случайный поддерживаемый отпечаток; выбор зависит от клиента'],
            'ip-version' => ['dual' => 'IPv4 и IPv6', 'ipv4' => 'только IPv4', 'ipv6' => 'только IPv6', 'ipv4-prefer' => 'предпочесть IPv4', 'ipv6-prefer' => 'предпочесть IPv6'],
            'dualStack' => ['USE_FIRST_IP' => 'первый адрес DNS', 'PREFER_IPv4' => 'предпочесть IPv4', 'PREFER_IPv6' => 'предпочесть IPv6', 'ONLY_IPv4' => 'только IPv4', 'ONLY_IPv6' => 'только IPv6'],
            'bbr-profile' => ['standard' => 'обычный баланс', 'conservative' => 'менее агрессивное увеличение скорости', 'aggressive' => 'более агрессивный набор скорости, возможны очереди и потери'],
            'type' => ['NONCE_TYPE_RANDOM' => 'оставить случайные байты', 'NONCE_TYPE_PRINTABLE' => 'печатные ASCII-символы', 'NONCE_TYPE_PRINTABLE_SUBSET' => 'ограниченный набор печатных символов', 'NONCE_TYPE_FIXED' => 'префикс из customHexStrings'],
            'spoof_method' => ['wrong-sequence' => 'номер TCP вне окна приёма', 'wrong-checksum' => 'неверная контрольная сумма TCP', 'wrong-ack' => 'неверный номер подтверждения', 'wrong-md5' => 'неприемлемая TCP-MD5 подпись', 'wrong-timestamp' => 'устаревшая TCP-метка времени; не поддерживается на macOS'],
            default => [],
        };
        foreach ($choices as $value => $meaning) $text .= "\n$value — $meaning.";
        return $text;
    }
}
